={
  "model": "llama3.2:3b",
  "stream": false,
  "format": "json",
  "prompt": "You write for Da Money Fam, a luxury hip-hop collective. Return ONLY valid JSON with keys: title, slug, excerpt, outline. slug must be lowercase with hyphens. excerpt is one sentence. outline is an array of 4 strings (section bullet points). Topic: a current trend in hip-hop, fashion, or culture."
}

parameters.jsCode:
const outlineRaw = $('Ollama Outline').first().json.response;
const expandRaw = $input.first().json.response;

let outline = null;
let expanded = null;
try { outline = JSON.parse(outlineRaw); } catch { outline = null; }
try { expanded = JSON.parse(expandRaw); } catch { expanded = null; }

const title = String(outline?.title || expanded?.title || 'DMF Daily').trim();
const slug = String(outline?.slug || expanded?.slug || `post-${Date.now()}`).trim();
const excerpt = String(outline?.excerpt || expanded?.excerpt || '').trim();

let content = String(expanded?.content || expanded?.body || '').trim();
if (!content && expandRaw && !expandRaw.trim().startsWith('{')) {
  content = expandRaw.trim();
}
if (!content && outline?.content) {
  content = String(outline.content).trim();
}
if (!content && excerpt) {
  content = `${excerpt}\n\n${excerpt} `.repeat(40).trim();
}

const words = content.split(/\s+/).filter(Boolean).length;
const usedFallback = !expandRaw || expandRaw.trim().startsWith('{') && !expanded?.content;
const isPadding = excerpt.length > 20 && content.split(excerpt).length > 4;
const is_published = Boolean(title && slug && words >= 100 && !isPadding && !usedFallback);

const covers = [
  '/store/merch/custom-dmf-t-shirt.png',
  '/store/merch/dmf-sweater-1.png',
  '/store/merch/dmf-sweater-2.png'
];
const start = new Date(new Date().getFullYear(), 0, 0);
const dayOfYear = Math.floor((Date.now() - start.getTime()) / 86400000);
const cover_image_url = covers[dayOfYear % covers.length];

return [{
  json: { slug, title, excerpt, content, cover_image_url, is_published }
}];
